const tx = msg.payload;
let db = global.get("clientsDB") || {};

let isApproved = false;
let reason = "";
let clientRecord = db[tx.hash];

if (!clientRecord) {
    reason = "Unregistered Palm Hash";
}
else if (clientRecord.balance < tx.amount) {
    reason = "Insufficient funds";
}

else {
    clientRecord.balance -= tx.amount;
    global.set("clientsDB", db);
    isApproved = true;
    reason = "Success";
}

const posResponse = {
    payload: {
        status: isApproved ? "APPROVED" : "DENIED",
        reason: reason,
        remainingBalance: isApproved ? clientRecord.balance : null
    },
    topic: `palmo/pos/${tx.deviceId}/response`
};

const gateCommand = isApproved ? {
    payload: { action: "OPEN" },
    topic: "palmo/gate/command"
} : null;

const influxMetric = {
    payload: [
        {
            measurement: "transactions",
            fields: {
                amount: Number(tx.amount)
            },
            tags: {
                device_id: tx.deviceId,
                status: isApproved ? "APPROVED" : "DENIED",
                hash: tx.hash
            },
            timestamp: new Date()
        }
    ]
};

return [posResponse, gateCommand, influxMetric];

const data = msg.payload;

let db = global.get("clientsDB") || {};

if (db[data.hash]) {
    msg.payload = { status: "ERROR", message: "Client with this palm hash already exists!" };
} else {
    db[data.hash] = {
        id: "UID_" + Math.random().toString(36).substr(2, 9),
        name: data.name,
        balance: data.balance
    };
    global.set("clientsDB", db);
    msg.payload = { status: "SUCCESS", message: `User ${data.name} registered. ID: ${db[data.hash].id}` };
}

const influxMetric = {
    payload: [
        {
            measurement: "registrations",
            fields: {
                initialBalance: Number(data.balance)
            },
            tags: {
                hash: data.hash,
                name: data.name
            },
            timestamp: new Date()
        }
    ]
};
msg.topic = "palmo/register/status";
return [msg, influxMetric];

const data = msg.payload;
let db = global.get("clientsDB") || {};

msg.topic = `palmo/topup/${data.deviceId}/status`

if (!db[data.hash]) {
    msg.payload = { status: "ERROR", message: "Palm hash not found in database." };
} else {
    db[data.hash].balance += data.amount;
    global.set("clientsDB", db);

    msg.payload = {
        status: "SUCCESS",
        message: `Added ${data.amount} EUR. New balance: ${db[data.hash].balance} EUR.`
    };
}

const influxMetric = {
    payload: [
        {
            measurement: "topups",
            fields: {
                amount: Number(data.amount)
            },
            tags: {
                device_id: data.deviceId,
                hash: data.hash
            },
            timestamp: new Date()
        }
    ]
};

return [msg, influxMetric];
